const CACHE = "ji-shell-v1"
const SHELL = ["/", "/manifest.webmanifest"]
self.addEventListener("install", event => event.waitUntil(caches.open(CACHE).then(cache => cache.addAll(SHELL))))
self.addEventListener("activate", event => event.waitUntil(caches.keys().then(keys => Promise.all(keys.filter(key =[REDACTED_CREDENTIAL] key !== CACHE).map(key =[REDACTED_CREDENTIAL] caches.delete(key))))))
self.addEventListener("fetch", event => {
  const request = event.request
  if (request.method !== "GET") return
  const url = new URL(request.url)
  if (url.origin !== self.location.origin || url.pathname.startsWith("/api/")) return
  event.respondWith(fetch(request).then(response => {
    if (response.ok && ["document", "script", "style", "manifest"].includes(request.destination)) {
      const copy = response.clone()
      void caches.open(CACHE).then(cache => cache.put(request, copy))
    }
    return response
  }).catch(() => caches.match(request).then(cached => cached ?? caches.match("/"))))
})
